UPDATE `item_template` SET `description` = '@Worldforged@吸上一口，你会觉得时间都慢了下来。他们称之为粉末恍惚。我称之为遗憾的人生选择。' WHERE `entry` = 415049 AND `description` = '@Worldforged@One whiff and you’ll swear time slows. They call it a powder trance. I call it regrettable life choices.';
UPDATE `item_template` SET `description` = '@Worldforged@最为精致的典范。' WHERE `entry` = 415054 AND `description` = '@Worldforged@The most exquisite exemplar.';
UPDATE `item_template` SET `description` = '@Worldforged@开辟通往宝藏的道路，或者把敌人剁成碎块，伙计！有些人就是更喜欢挥斧头！' WHERE `entry` = 415058 AND `description` = '@Worldforged@Carve yer way to treasure, or foes to pieces, matey! Some just prefer the swing of an axe!';
UPDATE `item_template` SET `description` = '@Worldforged@把耳朵贴上去，能隐隐听见大海。' WHERE `entry` = 415059 AND `description` = '@Worldforged@You can faintly hear the sea when you put your ear up to it.';
UPDATE `item_template` SET `description` = '@Worldforged@他们永远察觉不到，' WHERE `entry` = 415060 AND `description` = '@Worldforged@They never see it coming,';
