UPDATE `item_template` SET `description` = '@Worldforged@能活下来的人不多。' WHERE `entry` = 415093 AND `description` = '@Worldforged@Not many survive it.';
UPDATE `item_template` SET `description` = '@Worldforged@这只是借的……对吧？' WHERE `entry` = 415140 AND `description` = '@Worldforged@This is only being borrowed... Right?';
UPDATE `item_template` SET `description` = '@Worldforged@由荒芜之地的基岩塑成，这件遗物嗡鸣着大地的潜在之力。持用者能感到大地随其震荡与震颤而回应，每次敲击都产生共鸣。' WHERE `entry` = 415146 AND `description` = '@Worldforged@Shaped from Badlands bedrock, this relic hums with the latent power of the earth. Those who wield it feel the land itself respond to their shocks and quakes, resonating with each strike.';
UPDATE `item_template` SET `description` = '@Worldforged@大概还是别想它之前的用途了。' WHERE `entry` = 415151 AND `description` = '@Worldforged@Probably shouldn''t think about it''s previous use.';
UPDATE `item_template` SET `description` = '@Worldforged@注入着马尔图克缚地仪式的回响之力，这顶头巾与每次咒语共鸣，呼唤岩石与大地应你之命而起。' WHERE `entry` = 415160 AND `description` = '@Worldforged@Infused with the echoing power of Martuk’s earthbind rituals, this cowl resonates with every incantation, beckoning the rock and stone to rise at your command.';
UPDATE `item_template` SET `description` = '@Mythic@它拥有……让你动容的力量。' WHERE `entry` = 424091 AND `description` = '@Mythic@It has the power... to move you.';
