UPDATE `item_template` SET `description` = '@Mythic@很久以前被枢纽之王们盗走，这把权杖承载着纳鲁的正义之力。' WHERE `entry` = 427840 AND `description` = '@Mythic@Stolen long ago by the Nexus-Kings, the Scepter embodies the righteous power of the Naaru.';
