UPDATE `item_template` SET `description` = '@Worldforged@它仍闪着毒光。' WHERE `entry` = 450515 AND `description` = '@Worldforged@It still glints with poison.';
UPDATE `item_template` SET `description` = '@Worldforged@传说有一座孤峰，那里的闪电如钟表般准时，每逢满月便劈落一次。\n\n这根魔杖的木料取自一棵被劈中过不止一次、而是两次的树——它的力量如今织入了这件早已失落的雷瀑血脉遗物之中。' WHERE `entry` = 450525 AND `description` = '@Worldforged@Legends tell of a lone peak where lightning strikes like clockwork, once with every full moon. \n\nThe wand''s wood was taken from a tree struck not once, but twice—its power now woven into this relic of the long-lost Thunderfalls lineage.';
UPDATE `item_template` SET `description` = '@Worldforged@能可靠地保护你不被强盗伤害的枪……大体上。' WHERE `entry` = 450526 AND `description` = '@Worldforged@Guns that reliably protect you from Bandits... Mostly.';
UPDATE `item_template` SET `description` = '@Worldforged@你……拿走了……蜡烛？' WHERE `entry` = 450528 AND `description` = '@Worldforged@You... took... Candle?';
