UPDATE `item_template` SET `description` = '@Worldforged@我只希望能到那最后一座岛。对岸的鱼总是更大。' WHERE `entry` = 450551 AND `description` = '@Worldforged@I just wish I could''ve made it to that last island. The fish are always bigger on the other side.';
UPDATE `item_template` SET `description` = '@Worldforged@我算是走运的矿工吧？' WHERE `entry` = 450552 AND `description` = '@Worldforged@Am I a lucky miner or what?';
