UPDATE `item_template` SET `description` = '@Worldforged@曼克里克已经失去够多了……也许最好把它放回去。' WHERE `entry` = 450644 AND `description` = '@Worldforged@Mankrik has lost enough already... Maybe it''s best to just put this back.';
