UPDATE `item_template` SET `description` = '@Worldforged@地狱犬的角被取下后能在一天内重新长出，但这只失落的角里似乎仍残留着沙希尔的一部分力量。' WHERE `entry` = 1379460 AND `description` = '@Worldforged@Felhound''s are capable of regrowing their horns within a day if removed, but this lost horn seems to still contain a portion of Shahiar''s power.';
UPDATE `item_template` SET `description` = '@Worldforged@地狱犬的角被取下后能在一天内重新长出，但这只失落的角里似乎仍残留着沙希尔的一部分力量。' WHERE `entry` = 1379461 AND `description` = '@Worldforged@Felhound''s are capable of regrowing their horns within a day if removed, but this lost horn seems to still contain a portion of Shahiar''s power.';
UPDATE `item_template` SET `description` = '@Worldforged@对一枚早已湮没于时间中的强大戒指的仿制品。' WHERE `entry` = 1379468 AND `description` = '@Worldforged@An imitation of a much more powerful ring long since lost to time.';
UPDATE `item_template` SET `description` = '@Worldforged@它是对艾萨拉力量的隐喻，其威力似乎也相当字面。' WHERE `entry` = 1379470 AND `description` = '@Worldforged@A metaphorical representation of Azshara''s strength, its power seems to be quite literal as well.';
UPDATE `item_template` SET `description` = '@Worldforged@艾尔达拉将贝斯阿玛拉符文刻在这样的水晶上以守护城市，但即便是那股力量也不足以让它在天崩地裂中幸存。' WHERE `entry` = 1379471 AND `description` = '@Worldforged@Eldara inscribed Beth''Amara Runes onto crystals like this one to ward the city, yet even that power was not enough to save it from the Sundering.';
UPDATE `item_template` SET `description` = '@Worldforged@艾尔达拉将马克里符文刻在这样的武器上，用以抵御来犯者。赋予它活力的附魔早已消退，但它的运作方式看起来与现代弩颇为相似。' WHERE `entry` = 1379472 AND `description` = '@Worldforged@Eldara inscribed Markri runes onto weapons like this one to defend the city from attackers. The enchantments animating it have long since faded, but it looks to function similarly to a modern crossbow.';
UPDATE `item_template` SET `description` = '@Worldforged@这副护肩回响着高阶祭司辛-玛洛尔的微弱力量——一个至今仍令史学家困惑的谜团。' WHERE `entry` = 1379473 AND `description` = '@Worldforged@These shoulderguards carry a faint echo of High Priest Zin-Malor’s power—an enigma that continues to baffle historians.';
UPDATE `item_template` SET `description` = '@Worldforged@制作这些靴子时没有任何熊怪受到伤害。' WHERE `entry` = 1379475 AND `description` = '@Worldforged@No furbolg were harmed in the making of these boots.';
UPDATE `item_template` SET `description` = '@Worldforged@这片土地以她光辉之名命名，我们将以她的名义夺回它！' WHERE `entry` = 1379476 AND `description` = '@Worldforged@These lands bear the name of Her Radiance, and in her name shall we reclaim them!';
UPDATE `item_template` SET `description` = '@Worldforged@法杖上刻的符文仍在发光，那是早已从艾泽拉斯消失的古代书记官之力。' WHERE `entry` = 1379481 AND `description` = '@Worldforged@The runes engraved upon this staff still glow with the power of an ancient scribe who has long since vanished from Azeroth.';
UPDATE `item_template` SET `description` = '@Worldforged@地精工程学：记住，它只需要成功一次！' WHERE `entry` = 1379482 AND `description` = '@Worldforged@Goblin Engineering: Remember, it only has to work once!';
UPDATE `item_template` SET `description` = '@Worldforged@以农庄铁料锻造，受虔诚垦荒者的祝福' WHERE `entry` = 1379487 AND `description` = '@Worldforged@Forged from farmstead iron and blessed by faithful homesteaders';
UPDATE `item_template` SET `description` = '@Worldforged@曾穿着这副护肩的躯体已所剩无几，但织入破布中的残余魔法仍在延续。' WHERE `entry` = 1379509 AND `description` = '@Worldforged@Little remains of the body that once wore these pads, but the lingering magic woven into the tattered cloth still endures.';
UPDATE `item_template` SET `description` = '@Worldforged@这枚朴素的戒指上满是齿痕与爪印，讲述着一位再也没能从荒野归来的猎人的最后故事。' WHERE `entry` = 1379526 AND `description` = '@Worldforged@Scratched by teeth and claws, this humble ring tells the final tale of a hunter who never returned from the wild.';
UPDATE `item_template` SET `description` = '@Worldforged@由一位勇敢的骑士携带，他正踏上净化辛萨罗内苏醒之邪恶的征途。' WHERE `entry` = 1379538 AND `description` = '@Worldforged@Carried by a brave knight on a quest to cleanse the evil stirring within Jintha’Alor.';
UPDATE `item_template` SET `description` = '@Worldforged@与古老邪恶的微弱心跳共鸣。' WHERE `entry` = 1379539 AND `description` = '@Worldforged@Resonates with the faint heartbeat of an ancient evil.';
UPDATE `item_template` SET `description` = '@Worldforged@一本破旧的手册，整段被划掉，用粗体红墨水写上「-50 DKP！」。' WHERE `entry` = 1379543 AND `description` = '@Worldforged@A battered handbook with entire sections scribbled out and replaced by ‘-50 DKP!’ in bold, red ink.';
UPDATE `item_template` SET `description` = '@Worldforged@需尽快送达雷瓦图斯克村！' WHERE `entry` = 1379554 AND `description` = '@Worldforged@To be delivered with all haste to Ravantusk Village!';
UPDATE `item_template` SET `description` = '@Worldforged@微弱的嗡鸣诉说着一位坚定的萨满对抗蔓延的其拉虫群的最后坚守。' WHERE `entry` = 1379559 AND `description` = '@Worldforged@A faint hum speaks of a determined shaman’s last stand against the creeping Silithid hordes.';
UPDATE `item_template` SET `description` = '@Worldforged@洞穴中的魔法已深深渗入木质，使它以静谧而永恒的力量嗡鸣。' WHERE `entry` = 1379569 AND `description` = '@Worldforged@Magic from the Caverns has seeped deep into the wood, causing it to hum with quiet, timeless power.';
UPDATE `item_template` SET `description` = '@Worldforged@能把活干完。' WHERE `entry` = 1379579 AND `description` = '@Worldforged@Gets the job done.';
UPDATE `item_template` SET `description` = '@Worldforged@小心，镜片碎了，别让玻璃进眼睛！\n\n免责声明：此物品的镜片组件已损坏。请极其谨慎地操作，以免玻璃碎片造成眼部伤害。制造商对使用此损坏设备所导致的任何损害或不良状态效果不承担责任。请自行承担使用风险。' WHERE `entry` = 1379584 AND `description` = '@Worldforged@Watch out, the lens is broken, don''t get glass in your eyes!\n\nDISCLAIMER: This item features a compromised lens assembly. Handle with extreme caution to avoid ocular injury from glass fragments. Manufacturer assumes no liability for damages or adverse status effects resulting from the use of this damaged equipment. Use at your own risk.';
UPDATE `item_template` SET `description` = '@Worldforged@外观即自信！' WHERE `entry` = 1379588 AND `description` = '@Worldforged@Cosmetic confidence!';
