UPDATE `item_template` SET `description` = '@Worldforged@曾穿着这副护肩的躯体已所剩无几，但织入破布中的残余魔法仍在延续。' WHERE `entry` = 1381509 AND `description` = '@Worldforged@Little remains of the body that once wore these pads, but the lingering magic woven into the tattered cloth still endures.';
