UPDATE `item_template` SET `description` = '@Worldforged@微弱的嗡鸣诉说着一位坚定的萨满对抗蔓延的其拉虫群的最后坚守。' WHERE `entry` = 1381559 AND `description` = '@Worldforged@A faint hum speaks of a determined shaman’s last stand against the creeping Silithid hordes.';
