UPDATE `item_template` SET `description` = '@Worldforged@它似乎已在沼泽里躺了很久，但尽管生锈，其上附魔仍保有力量。' WHERE `entry` = 1382264 AND `description` = '@Worldforged@It seems to have been sitting in the marsh for a very long time, but the enchantments on it have kept their power in spite of the rust.';
