UPDATE `item_template` SET `description` = '@Worldforged@战斗中，治疗与法力药水与其他药水使用独立的冷却时间。' WHERE `entry` = 1384156 AND `description` = '@Worldforged@Healing and Mana potions can be used on separate cooldown from other potions in combat.';
