UPDATE `item_template` SET `description` = '@Worldforged@以最精良的地精式巧思打造！此装置的制造者不对任何其他意外副作用承担责任。' WHERE `entry` = 1384280 AND `description` = '@Worldforged@Crafted with the finest gnomish ingenuity! The creator of this device assumes no responsibility for any other unintended side effects.';
