UPDATE `item_template` SET `description` = '@Worldforged@握在手中，它低声嗡鸣，间或夹杂着微弱的爆裂声。也许还是别碰它为好。' WHERE `entry` = 1385433 AND `description` = '@Worldforged@Held in your grasp, it hums softly, punctuated by faint, crackle. Perhaps it''s best left alone.';
