UPDATE `item_template` SET `description` = '@Worldforged@注入扭曲的魔法，这块金属碎片随着古老的嗡鸣脉动。' WHERE `entry` = 1387297 AND `description` = '@Worldforged@Infused with twisted magic, the metallic shard pulses with an ancient buzz.';
