UPDATE `item_template` SET `description` = '@Worldforged@意外地舒适！' WHERE `entry` = 1387316 AND `description` = '@Worldforged@Surprisingly Comfortable!';
UPDATE `item_template` SET `description` = '@Worldforged@它让他们永远睡去。' WHERE `entry` = 1387328 AND `description` = '@Worldforged@It makes them sleep FOREVER.';
