UPDATE `item_template` SET `description` = '@Worldforged@这件投掷武器曾是「神奇四人组」收藏的一部分。别被这个双关糊弄了，它的杀伤力依然足以支撑一场全球巡演。' WHERE `entry` = 1387355 AND `description` = '@Worldforged@This throwing weapon was once part of a Fab Four collection. Don’t let the pun fool you. It still packs a hit worthy of a worldwide tour.';
UPDATE `item_template` SET `description` = '@Worldforged@从钓鲈鱼到轰然开嘲' WHERE `entry` = 1387405 AND `description` = '@Worldforged@From luring bass to blasting sass';
UPDATE `item_template` SET `description` = '@Worldforged@不过挺酷的披风' WHERE `entry` = 1387409 AND `description` = '@Worldforged@Cool Cloak Though';
UPDATE `item_template` SET `description` = '@Worldforged@戴着这东西可看不清……' WHERE `entry` = 1387429 AND `description` = '@Worldforged@Hard to see with this thing on...';
UPDATE `item_template` SET `description` = '@Worldforged@握在手中，它低声嗡鸣，间或夹杂着微弱的爆裂声。也许还是别碰它为好。' WHERE `entry` = 1387433 AND `description` = '@Worldforged@Held in your grasp, it hums softly, punctuated by faint, crackle. Perhaps it''s best left alone.';
UPDATE `item_template` SET `description` = '@Worldforged@得保持跑道干净才能达到最佳速度' WHERE `entry` = 1387438 AND `description` = '@Worldforged@Gotta keep the runway clean for optimal speeds';
