UPDATE `item_template` SET `description` = '@Worldforged@趁原料尚未完全混合，研究冬泉火酒，并学会如何仿制它。' WHERE `entry` = 1388263 AND `description` = '@Worldforged@Study the Winterfall Firewater before its ingredients have fully mixed and learn how to replicate it.';
UPDATE `item_template` SET `description` = '@Worldforged@他们说是给客人用的。' WHERE `entry` = 1388282 AND `description` = '@Worldforged@They say it’s for guests.';
