UPDATE `item_template` SET `description` = '@Worldforged@取自崖行者尸骸雕刻而成。从熊怪的遭遇看，巨人们对这件事可不太满意。' WHERE `entry` = 1393449 AND `description` = '@Worldforged@Carved from the body of a Cliffwalker. Judging by the furbolgs'' fate, the giants were none too happy about this.';
UPDATE `item_template` SET `description` = '@Worldforged@这把古老竖琴发出柔和而悦耳的鸣响。你不禁好奇它这些年是如何一直未被动过……' WHERE `entry` = 1393450 AND `description` = '@Worldforged@A soft, melodic hum resonates from this ancient lyre. You can''t help wondering how it''s remained untouched for all these years...';
UPDATE `item_template` SET `description` = '@Worldforged@费了些力气，你终于从古雕像上取下了这枚印章戒指。' WHERE `entry` = 1393454 AND `description` = '@Worldforged@With some effort, you were finally able to remove this signet from the ancient statue.';
UPDATE `item_template` SET `description` = '@Worldforged@她的船已经坠毁，看来她现在不必再让一只眼适应黑暗了。' WHERE `entry` = 1393456 AND `description` = '@Worldforged@With her ship crashed, it doesn''t seem like she needs to keep one eye adapted to the dark right now.';
UPDATE `item_template` SET `description` = '@Worldforged@经过仔细隔热处理，以防化学品或炉灶烫伤。' WHERE `entry` = 1393458 AND `description` = '@Worldforged@Carefully insulated to protect against burns from chemicals or the stove.';
UPDATE `item_template` SET `description` = '@Worldforged@对一枚早已湮没于时间中的强大戒指的仿制品。' WHERE `entry` = 1393468 AND `description` = '@Worldforged@An imitation of a much more powerful ring long since lost to time.';
UPDATE `item_template` SET `description` = '@Worldforged@它是对艾萨拉力量的隐喻，其威力似乎也相当字面。' WHERE `entry` = 1393470 AND `description` = '@Worldforged@A metaphorical representation of Azshara''s strength, its power seems to be quite literal as well.';
UPDATE `item_template` SET `description` = '@Worldforged@艾尔达拉将贝斯阿玛拉符文刻在这样的水晶上以守护城市，但即便是那股力量也不足以让它在天崩地裂中幸存。' WHERE `entry` = 1393471 AND `description` = '@Worldforged@Eldara inscribed Beth''Amara Runes onto crystals like this one to ward the city, yet even that power was not enough to save it from the Sundering.';
UPDATE `item_template` SET `description` = '@Worldforged@艾尔达拉将马克里符文刻在这样的武器上，用以抵御来犯者。赋予它活力的附魔早已消退，但它的运作方式看起来与现代弩颇为相似。' WHERE `entry` = 1393472 AND `description` = '@Worldforged@Eldara inscribed Markri runes onto weapons like this one to defend the city from attackers. The enchantments animating it have long since faded, but it looks to function similarly to a modern crossbow.';
UPDATE `item_template` SET `description` = '@Worldforged@这副护肩回响着高阶祭司辛-玛洛尔的微弱力量——一个至今仍令史学家困惑的谜团。' WHERE `entry` = 1393473 AND `description` = '@Worldforged@These shoulderguards carry a faint echo of High Priest Zin-Malor’s power—an enigma that continues to baffle historians.';
UPDATE `item_template` SET `description` = '@Worldforged@制作这些靴子时没有任何熊怪受到伤害。' WHERE `entry` = 1393475 AND `description` = '@Worldforged@No furbolg were harmed in the making of these boots.';
UPDATE `item_template` SET `description` = '@Worldforged@这片土地以她光辉之名命名，我们将以她的名义夺回它！' WHERE `entry` = 1393476 AND `description` = '@Worldforged@These lands bear the name of Her Radiance, and in her name shall we reclaim them!';
UPDATE `item_template` SET `description` = '@Worldforged@法杖上刻的符文仍在发光，那是早已从艾泽拉斯消失的古代书记官之力。' WHERE `entry` = 1393481 AND `description` = '@Worldforged@The runes engraved upon this staff still glow with the power of an ancient scribe who has long since vanished from Azeroth.';
UPDATE `item_template` SET `description` = '@Worldforged@地精工程学：记住，它只需要成功一次！' WHERE `entry` = 1393482 AND `description` = '@Worldforged@Goblin Engineering: Remember, it only has to work once!';
UPDATE `item_template` SET `description` = '@Worldforged@以农庄铁料锻造，受虔诚垦荒者的祝福' WHERE `entry` = 1393487 AND `description` = '@Worldforged@Forged from farmstead iron and blessed by faithful homesteaders';
UPDATE `item_template` SET `description` = '@Worldforged@曾穿着这副护肩的躯体已所剩无几，但织入破布中的残余魔法仍在延续。' WHERE `entry` = 1393509 AND `description` = '@Worldforged@Little remains of the body that once wore these pads, but the lingering magic woven into the tattered cloth still endures.';
UPDATE `item_template` SET `description` = '@Worldforged@这枚朴素的戒指上满是齿痕与爪印，讲述着一位再也没能从荒野归来的猎人的最后故事。' WHERE `entry` = 1393526 AND `description` = '@Worldforged@Scratched by teeth and claws, this humble ring tells the final tale of a hunter who never returned from the wild.';
UPDATE `item_template` SET `description` = '@Worldforged@由一位勇敢的骑士携带，他正踏上净化辛萨罗内苏醒之邪恶的征途。' WHERE `entry` = 1393538 AND `description` = '@Worldforged@Carried by a brave knight on a quest to cleanse the evil stirring within Jintha’Alor.';
UPDATE `item_template` SET `description` = '@Worldforged@与古老邪恶的微弱心跳共鸣。' WHERE `entry` = 1393539 AND `description` = '@Worldforged@Resonates with the faint heartbeat of an ancient evil.';
UPDATE `item_template` SET `description` = '@Worldforged@一本破旧的手册，整段被划掉，用粗体红墨水写上「-50 DKP！」。' WHERE `entry` = 1393543 AND `description` = '@Worldforged@A battered handbook with entire sections scribbled out and replaced by ‘-50 DKP!’ in bold, red ink.';
UPDATE `item_template` SET `description` = '@Worldforged@微弱的嗡鸣诉说着一位坚定的萨满对抗蔓延的其拉虫群的最后坚守。' WHERE `entry` = 1393559 AND `description` = '@Worldforged@A faint hum speaks of a determined shaman’s last stand against the creeping Silithid hordes.';
UPDATE `item_template` SET `description` = '@Worldforged@洞穴中的魔法已深深渗入木质，使它以静谧而永恒的力量嗡鸣。' WHERE `entry` = 1393569 AND `description` = '@Worldforged@Magic from the Caverns has seeped deep into the wood, causing it to hum with quiet, timeless power.';
UPDATE `item_template` SET `description` = '@Worldforged@能把活干完。' WHERE `entry` = 1393579 AND `description` = '@Worldforged@Gets the job done.';
UPDATE `item_template` SET `description` = '@Worldforged@小心，镜片碎了，别让玻璃进眼睛！\n\n免责声明：此物品的镜片组件已损坏。请极其谨慎地操作，以免玻璃碎片造成眼部伤害。制造商对使用此损坏设备所导致的任何损害或不良状态效果不承担责任。请自行承担使用风险。' WHERE `entry` = 1393584 AND `description` = '@Worldforged@Watch out, the lens is broken, don''t get glass in your eyes!\n\nDISCLAIMER: This item features a compromised lens assembly. Handle with extreme caution to avoid ocular injury from glass fragments. Manufacturer assumes no liability for damages or adverse status effects resulting from the use of this damaged equipment. Use at your own risk.';
UPDATE `item_template` SET `description` = '@Worldforged@外观即自信！' WHERE `entry` = 1393588 AND `description` = '@Worldforged@Cosmetic confidence!';
UPDATE `item_template` SET `description` = '@Worldforged@种子随生命搏动，你感到自己长高了一寸。' WHERE `entry` = 1393593 AND `description` = '@Worldforged@The seed pulses with life and you feel yourself growing an inch taller.';
UPDATE `item_template` SET `description` = '@Worldforged@留下以纪念一位逝去的旧友。' WHERE `entry` = 1393672 AND `description` = '@Worldforged@Left to honor a fallen friend of the past.';
UPDATE `item_template` SET `description` = '@Worldforged@用来双手砍树！' WHERE `entry` = 1393705 AND `description` = '@Worldforged@For cutting down trees with both hands!';
UPDATE `item_template` SET `description` = '@Worldforged@一名早在人类初踏足之前便已生死轮回的巨魔的磨损股骨。接过神殿守护者职责的人都清楚这份荣耀的可怕代价：永恒的奴役。' WHERE `entry` = 1393903 AND `description` = '@Worldforged@Worn femur of a troll who lived and perished long before mankind’s first steps. Those who took the temple’s mantle of guardian did so knowing the dreadful cost of such honor: an eternity of servitude.';
UPDATE `item_template` SET `description` = '@Worldforged@我承认我不属于任何哲学。我属于现实世界。因为现实不容于任何意识形态。那些东西都是抽象之物，是我们害怕提问又得不到答案时抓来的安慰。' WHERE `entry` = 1393910 AND `description` = '@Worldforged@I confess I belong to no philosophy. I belong to the real world. For reality fits within no ideology. Such things are abstractions, comforts we embraced out of fear of asking questions without the promise of answers.';
UPDATE `item_template` SET `description` = '@Worldforged@三图腾最高大战士的礼物。莫里加·空蹄自他幼时便盯上了他，尽管两人相隔多年，她仍谋划着将他占为伴侣，希望有朝一日驱使他去对抗他的父亲。她做到了。而他死了。' WHERE `entry` = 1393912 AND `description` = '@Worldforged@Gift of the tallest warrior of Three Totems. Morriga Hollowhoof marked him from childhood, and though many years lay between them, she conspired to claim him as her mate, hoping one day to drive him against his father. She did. And he died.';
UPDATE `item_template` SET `description` = '@Worldforged@在凯恩家族墓穴旁被掘出的棺盖，遭狗头人洗劫。它们在这片土地上十分少见，因为它们知道土壤之下住着什么……那让它们彻骨生寒。' WHERE `entry` = 1393918 AND `description` = '@Worldforged@Lid of a coffin unearthed beside the Cain family crypt, plundered by kobolds. Their presence in these lands is rare, for they know what dwells beneath the soil… and it chills them to the marrow.';
UPDATE `item_template` SET `description` = '@Worldforged@光辉镇狂信徒所戴的头盔。靠近的人都会感到一阵轻微的刺痛。这个教派的起源仍旧成谜，有人低声提起一位辐射之神，祂曾在光辉陛下面前显现，并赋予他神圣的使命。' WHERE `entry` = 1393921 AND `description` = '@Worldforged@Helm worn by the zealots of Radiance Town. A faint tingling spreads to those who draw near. Though the cult’s origin is shrouded, some whisper of a god of radiation, who appeared before His Radiant Majesty and granted him divine purpose.';
UPDATE `item_template` SET `description` = '@Worldforged@用巨兀鹫巢枝制成的长柄武器。据说这些枝条原本都属于一棵世界之树，为阻挡更大的灾祸而被伐倒。' WHERE `entry` = 1393925 AND `description` = '@Worldforged@Polearm fashioned from a branch of the Great Vulture’s nest. It is said the branches all once belonged to a World Tree, felled to stave off some calamity yet greater.';
UPDATE `item_template` SET `description` = '@Mythic Raid@黑龙军团育母的头' WHERE `entry` = 1397269 AND `description` = '@Mythic Raid@The head of the Black Dragonflight''s Brood Mother';
UPDATE `item_template` SET `description` = '@Mythic Raid@ 一份官方文件，证明奥妮克希亚已死亡。\n\n把这份文件交给以下任意一人即可领取奖励。\n  - 奥格瑞玛银行外的伦萨克督军。\n  - 暴风城贸易区外的马廷利少校。\n  - 藏宝海湾旅店上层船只上的里维加兹男爵。' WHERE `entry` = 1397270 AND `description` = '@Mythic Raid@ An official document, certifying Onyxia''s death.\n\nBring this document to one of the following to reap your rewards.\n  - Overlord Runthak outside of Orgrimmar Bank.\n  - Major Mattingly outside of Trade District in Stormwind.\n  - Baron Revilgaz on the upper boat of Booty Bay inn.';
UPDATE `item_template` SET `description` = '@Mythic Raid@奈法利安的头颅：死亡之翼的子嗣。' WHERE `entry` = 1397271 AND `description` = '@Mythic Raid@The head of Nefarian: Brood of Deathwing.';
UPDATE `item_template` SET `description` = '@Mythic Raid@一份官方文件，证明奈法利安已死亡。\n\n把这份文件交给以下任意一人即可领取奖励。\n - 格罗玛什要塞的萨尔（奥格瑞玛）。\n - 暴风要塞的大领主伯瓦尔·弗塔根（暴风城）。\n - 藏宝海湾旅店上层船只上的里维加兹男爵。' WHERE `entry` = 1397272 AND `description` = '@Mythic Raid@An official document, certifying Nefarian''s death.\n\nBring this document to one of the following to reap your rewards.\n - Thrall in Grommash Hold (Orgrimmar).\n - Highlord Bolvar Fordragon in Stormwind Keep (Stormwind).\n - Baron Revilgaz on the upper boat of Booty Bay inn.';
UPDATE `item_template` SET `description` = '@Wrath of the Lich King@通过征服诺森德最凶猛的生物获得。' WHERE `entry` = 1400752 AND `description` = '@Wrath of the Lich King@Obtained through conquering Northrend''s fiercest creatures.';
UPDATE `item_template` SET `description` = '@Mythic Raid@这是第 3 阶护腕部位的全局代币。可在暴风城（马廷利少校）或奥格瑞玛（伦萨克督军）的商人处兑换。' WHERE `entry` = 1402262 AND `description` = '@Mythic Raid@This Token is a Global Token for Tier 3 Bracer Slot items. This is Exchangeable at a Vendor found in Stormwind (Major Mattingly) or Orgrimmar (Overlord Runthak).';
