UPDATE `item_template` SET `description` = '@Mythic Raid@小瓶仍然完好，里面还剩少量永恒之井的水。' WHERE `entry` = 1450002 AND `description` = '@Mythic Raid@The vial is still intact, containing a small amount of the water from the Well of Eternity.';
